	('2fee032e-7dea-4914-a672-598c9ce3963a', 'visitor_welcome', 'Welcome to our family, {{firstName}}!', '<div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; padding: 40px; color: #1e293b; line-height: 1.6;">
